import React, { useEffect, useState } from 'react';
import { Button, Input, Select, dispatchAppToast } from '@linm-soft-org/linm-web-common-components';
import { useParams, useSearchParams } from 'react-router-dom';
import { DocumentFormHeader } from '../../../components/layout/DocumentFormHeader';
import { UnsavedChangesModal } from '../../../components/form';
import { useUnsavedChangesGuard } from '../../../hooks/useUnsavedChangesGuard';
import { useInAppNavigate } from '../../../router/useInAppNavigate';
import { useAppDispatch } from '../../../store/hooks';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import {
  createPeriodicAllocationVoucher,
  getPeriodicAllocationAccountFlags,
  getPeriodicAllocationVoucher,
  unpostPeriodicAllocationVoucher,
  updatePeriodicAllocationVoucher,
  type PeriodicAllocationWrite,
  type PeriodicAllocationWriteLine,
} from '../../../services/kt/periodicAllocationVouchers';
import df from '../../../styles/documentForm.module.css';

interface LineState {
  tkNo: string;
  tkCo: string;
  ngayCt00: string;
  tienNt: string;
  dienGiaii: string;
  tien: string;
  maVvI: string;
  maHdI: string;
  maPhiI: string;
  maTtlnI: string;
  maTtcpI: string;
  maBpI: string;
  maKhN: string;
  maKhC: string;
}

interface FormState {
  maGd: string;
  maPost: string;
  ngayCt: string;
  ngayLct: string;
  soCt: string;
  soLo: string;
  ngayLo: string;
  maQuyen: string;
  dienGiai: string;
  maNt: string;
  tyGia: string;
  soKyPb: string;
  ngayPb: string;
  tkNoH: string;
  tkCoH: string;
  tTtNt: string;
  tTt: string;
  lines: LineState[];
}

const emptyLine = (): LineState => ({
  tkNo: '',
  tkCo: '',
  ngayCt00: '',
  tienNt: '',
  dienGiaii: '',
  tien: '',
  maVvI: '',
  maHdI: '',
  maPhiI: '',
  maTtlnI: '',
  maTtcpI: '',
  maBpI: '',
  maKhN: '',
  maKhC: '',
});

function today(): string {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function createDefault(): FormState {
  const date = today();
  return {
    maGd: '1',
    maPost: '9',
    ngayCt: date,
    ngayLct: date,
    soCt: '',
    soLo: '',
    ngayLo: '',
    maQuyen: '',
    dienGiai: '',
    maNt: '',
    tyGia: '',
    soKyPb: '',
    ngayPb: '',
    tkNoH: '',
    tkCoH: '',
    tTtNt: '0',
    tTt: '0',
    lines: [],
  };
}

function dateOrEmpty(value: string | null | undefined): string {
  return value ? value.slice(0, 10) : '';
}

function nullText(value: string): string | null {
  const text = value.trim();
  return text ? text : null;
}

function nullNumber(value: string): number | null {
  const text = value.trim();
  if (!text) return null;
  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : null;
}

function toWrite(form: FormState): PeriodicAllocationWrite {
  const lines: PeriodicAllocationWriteLine[] = form.lines.map(line => ({
    tkNo: nullText(line.tkNo),
    tkCo: nullText(line.tkCo),
    ngayCt00: nullText(line.ngayCt00),
    tienNt: nullNumber(line.tienNt),
    dienGiaii: nullText(line.dienGiaii),
    tien: nullNumber(line.tien),
    maVvI: nullText(line.maVvI),
    maHdI: nullText(line.maHdI),
    maPhiI: nullText(line.maPhiI),
    maTtlnI: nullText(line.maTtlnI),
    maTtcpI: nullText(line.maTtcpI),
    maBpI: nullText(line.maBpI),
    maKhN: nullText(line.maKhN),
    maKhC: nullText(line.maKhC),
  }));
  return {
    maGd: '1',
    maPost: '9',
    maCt: 'PB6',
    ngayCt: nullText(form.ngayCt),
    ngayLct: nullText(form.ngayLct),
    soCt: nullText(form.soCt),
    soLo: nullText(form.soLo),
    ngayLo: nullText(form.ngayLo),
    maQuyen: nullText(form.maQuyen),
    dienGiai: nullText(form.dienGiai),
    maNt: nullText(form.maNt),
    tyGia: nullNumber(form.tyGia),
    soKyPb: nullNumber(form.soKyPb),
    ngayPb: nullText(form.ngayPb),
    tkNoH: nullText(form.tkNoH),
    tkCoH: nullText(form.tkCoH),
    tTtNt: nullNumber(form.tTtNt),
    tTt: nullNumber(form.tTt),
    lines,
  };
}

const Pb6FormPage: React.FC = () => {
  const navigate = useInAppNavigate();
  const dispatch = useAppDispatch();
  const { sttRec: routeSttRec } = useParams();
  const [searchParams] = useSearchParams();
  const copyFrom = searchParams.get('copyFrom') ?? '';
  const isView = searchParams.get('mode') === 'view';
  const isNewRoute = !routeSttRec;
  const isCopy = isNewRoute && copyFrom.length > 0;
  const isCreate = isNewRoute && !isCopy;
  const isEdit = !isNewRoute && !isView;

  const [form, setForm] = useState<FormState>(createDefault);
  const [loading, setLoading] = useState(!isCreate);
  const [loadError, setLoadError] = useState('');
  const [error, setError] = useState('');
  const [saving, setSaving] = useState(false);
  const [unposting, setUnposting] = useState(false);
  const [selectedLineIndex, setSelectedLineIndex] = useState<number | null>(null);
  const [isDirty, setIsDirty] = useState(false);

  const { showUnsavedModal, guardedAction, confirmLeave, cancelLeave } = useUnsavedChangesGuard(isDirty, !isView);

  useEffect(() => {
    if (isCreate) {
      setForm(createDefault());
      setIsDirty(false);
      setLoading(false);
      setLoadError('');
      return;
    }
    const key = isCopy ? copyFrom : routeSttRec;
    if (!key) return;
    let cancelled = false;
    setLoading(true);
    setLoadError('');
    void getPeriodicAllocationVoucher(key)
      .then(dto => {
        if (cancelled) return;
        setForm({
          maGd: '1',
          maPost: '9',
          ngayCt: dateOrEmpty(dto.ngayCt),
          ngayLct: dateOrEmpty(dto.ngayLct),
          soCt: dto.soCt ?? '',
          soLo: dto.soLo ?? '',
          ngayLo: dateOrEmpty(dto.ngayLo),
          maQuyen: dto.maQuyen ?? '',
          dienGiai: dto.dienGiai ?? '',
          maNt: dto.maNt ?? '',
          tyGia: dto.tyGia == null ? '' : String(dto.tyGia),
          soKyPb: dto.soKyPb == null ? '' : String(dto.soKyPb),
          ngayPb: dateOrEmpty(dto.ngayPb),
          tkNoH: dto.tkNoH ?? '',
          tkCoH: dto.tkCoH ?? '',
          tTtNt: dto.tTtNt == null ? '0' : String(dto.tTtNt),
          tTt: dto.tTt == null ? '0' : String(dto.tTt),
          lines: (dto.lines ?? []).map(line => ({
            tkNo: line.tkNo ?? '',
            tkCo: line.tkCo ?? '',
            ngayCt00: dateOrEmpty(line.ngayCt00),
            tienNt: line.tienNt == null ? '' : String(line.tienNt),
            dienGiaii: line.dienGiaii ?? '',
            tien: line.tien == null ? '' : String(line.tien),
            maVvI: line.maVvI ?? '',
            maHdI: line.maHdI ?? '',
            maPhiI: line.maPhiI ?? '',
            maTtlnI: line.maTtlnI ?? '',
            maTtcpI: line.maTtcpI ?? '',
            maBpI: line.maBpI ?? '',
            maKhN: line.maKhN ?? '',
            maKhC: line.maKhC ?? '',
          })),
        });
        setIsDirty(false);
      })
      .catch(err => {
        if (cancelled) return;
        setLoadError(getApiErrorMessage(err, 'Không tìm thấy bút toán phân bổ định kỳ'));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [isCreate, isCopy, copyFrom, routeSttRec]);

  const patch = (partial: Partial<FormState>) => {
    setForm(prev => ({ ...prev, ...partial }));
    setIsDirty(true);
  };

  const patchLine = (index: number, key: keyof LineState, value: string) => {
    setForm(prev => ({
      ...prev,
      lines: prev.lines.map((line, i) => (i === index ? { ...line, [key]: value } : line)),
    }));
    setIsDirty(true);
  };

  const addLine = () => {
    setForm(prev => ({ ...prev, lines: [...prev.lines, emptyLine()] }));
    setSelectedLineIndex(form.lines.length);
    setIsDirty(true);
  };

  const removeLine = () => {
    if (selectedLineIndex == null) return;
    setForm(prev => ({ ...prev, lines: prev.lines.filter((_, i) => i !== selectedLineIndex) }));
    setSelectedLineIndex(null);
    setIsDirty(true);
  };

  const validateClient = async (): Promise<string | null> => {
    if (form.lines.length === 0) return null;
    for (const line of form.lines) {
      if (!line.tkNo.trim()) return 'Bạn chưa nhập tài khoản nợ';
      if (!line.tkCo.trim()) return 'Bạn chưa nhập tài khoản có';
    }
    const codes = Array.from(new Set(
      form.lines.flatMap(line => [line.tkNo.trim(), line.tkCo.trim()]).filter(Boolean),
    ));
    const flags = await getPeriodicAllocationAccountFlags(codes.join(','));
    const tkCn = new Map(flags.items.map(item => [item.code.trim().toLowerCase(), item.tkCn]));
    for (const line of form.lines) {
      const tkNo = line.tkNo.trim();
      const tkCo = line.tkCo.trim();
      const maKhN = line.maKhN.trim();
      if (tkCn.get(tkNo.toLowerCase()) === 1 && !maKhN) {
        return `Tài khoản hạch toán nợ [${tkNo}] là tài khoản công nợ bạn phải nhập đối tượng nợ`;
      }
      if (tkCn.get(tkCo.toLowerCase()) === 1 && !maKhN) {
        return `Tài khoản hạch toán có [${tkCo}] là tài khoản công nợ bạn phải nhập đối tượng có`;
      }
    }
    return null;
  };

  const onSave = async () => {
    setSaving(true);
    setError('');
    try {
      const blocked = await validateClient();
      if (blocked) {
        setError(blocked);
        dispatchAppToast(dispatch, { type: 'error', message: blocked });
        return;
      }
      const body = toWrite(form);
      const saved = isNewRoute
        ? await createPeriodicAllocationVoucher(body)
        : await updatePeriodicAllocationVoucher(routeSttRec as string, body);
      setIsDirty(false);
      dispatchAppToast(dispatch, { type: 'success', message: 'Đã lưu bút toán phân bổ định kỳ' });
      navigate(`/kt/pb6/${saved.sttRec}`);
    } catch (err) {
      const message = getApiErrorMessage(err, 'Lưu thất bại');
      setError(message);
      dispatchAppToast(dispatch, { type: 'error', message });
    } finally {
      setSaving(false);
    }
  };

  const onUnpost = async () => {
    if (!routeSttRec) return;
    setUnposting(true);
    setError('');
    try {
      await unpostPeriodicAllocationVoucher(routeSttRec);
      setIsDirty(false);
      dispatchAppToast(dispatch, { type: 'success', message: 'Đã xóa ghi bút toán phân bổ định kỳ' });
    } catch (err) {
      const message = getApiErrorMessage(err, 'Xóa ghi thất bại');
      setError(message);
      dispatchAppToast(dispatch, { type: 'error', message });
    } finally {
      setUnposting(false);
    }
  };

  const title = isView
    ? 'Xem bút toán phân bổ định kỳ'
    : isEdit
      ? 'Sửa bút toán phân bổ định kỳ'
      : 'Thêm bút toán phân bổ định kỳ';
  const locked = isView;
  const showGrid = !loadError;

  return (
    <div className={df.page} data-testid="ct-pb6-form">
      <DocumentFormHeader
        testIdPrefix="ct-pb6"
        title={title}
        isNew={isCreate || isCopy}
        isReadOnly={isView}
        saving={saving}
        saveLabel="Lưu"
        saveEditLabel="Lưu"
        onBack={() => guardedAction(() => navigate('/kt/pb6'))}
        onSave={showGrid && !isView ? () => { void onSave(); } : undefined}
        extraActions={isEdit ? (
          <Button
            variant="secondary"
            data-testid="ct-pb6-unpost-btn"
            loading={unposting}
            onClick={() => { void onUnpost(); }}
          >
            Xóa ghi
          </Button>
        ) : undefined}
      />
      {loading ? <div className={df.loading}>Đang tải...</div> : null}
      {loadError ? <div className={df.errorBanner}>{loadError}</div> : null}
      {error ? <div className={df.errorBanner}>{error}</div> : null}
      {showGrid && !loading ? (
        <>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Chứng từ</h2>
            <div className={df.row4}>
              <Select
                label="Loại giao dịch"
                data-testid="ct-pb6-field-maGd"
                value={form.maGd}
                disabled
                options={[{ value: '1', label: 'Phiếu phân bổ định kỳ' }]}
                onChange={() => undefined}
              />
              <Select
                label="Trạng thái"
                data-testid="ct-pb6-field-maPost"
                value={form.maPost}
                disabled
                options={[{ value: '9', label: 'Hạch toán sổ cái' }]}
                onChange={() => undefined}
              />
              <DateField label="Ngày C.từ" testId="ct-pb6-field-ngayCt" value={form.ngayCt} disabled={locked} onChange={value => patch({ ngayCt: value })} />
              <DateField label="Ngày lập chứng từ" testId="ct-pb6-field-ngayLct" value={form.ngayLct} disabled={locked} onChange={value => patch({ ngayLct: value })} />
              <TextField label="Số C.từ" testId="ct-pb6-field-soCt" value={form.soCt} maxLength={30} disabled={locked} onChange={value => patch({ soCt: value })} />
              <TextField label="Số lô" testId="ct-pb6-field-soLo" value={form.soLo} maxLength={30} disabled={locked} onChange={value => patch({ soLo: value })} />
              <DateField label="Ngày lô" testId="ct-pb6-field-ngayLo" value={form.ngayLo} disabled={locked} onChange={value => patch({ ngayLo: value })} />
              <TextField label="Quyền" testId="ct-pb6-field-maQuyen" value={form.maQuyen} maxLength={30} disabled={locked} onChange={value => patch({ maQuyen: value })} />
              <div className={df.spanCol2}>
                <TextField label="Diễn giải" testId="ct-pb6-field-dienGiai" value={form.dienGiai} maxLength={200} disabled={locked} onChange={value => patch({ dienGiai: value })} />
              </div>
              <TextField label="Ngoại tệ" testId="ct-pb6-field-maNt" value={form.maNt} maxLength={3} disabled={locked} onChange={value => patch({ maNt: value })} />
              <TextField label="Tỷ giá" testId="ct-pb6-field-tyGia" value={form.tyGia} inputMode="decimal" disabled={locked} onChange={value => patch({ tyGia: value })} />
              <TextField label="Số kỳ" testId="ct-pb6-field-soKyPb" value={form.soKyPb} inputMode="numeric" disabled={locked} onChange={value => patch({ soKyPb: value })} />
              <DateField label="Ngày bắt đầu" testId="ct-pb6-field-ngayPb" value={form.ngayPb} disabled={locked} onChange={value => patch({ ngayPb: value })} />
              <TextField label="Tk nợ" testId="ct-pb6-field-tkNoH" value={form.tkNoH} maxLength={30} disabled={locked} onChange={value => patch({ tkNoH: value })} />
              <TextField label="Tk có" testId="ct-pb6-field-tkCoH" value={form.tkCoH} maxLength={30} disabled={locked} onChange={value => patch({ tkCoH: value })} />
              <TextField label="Giá trị phân bổ NT" testId="ct-pb6-field-tTtNt" value={form.tTtNt} inputMode="decimal" disabled={locked} onChange={value => patch({ tTtNt: value })} />
              <TextField label="Giá trị phân bổ" testId="ct-pb6-field-tTt" value={form.tTt} inputMode="decimal" disabled={locked} onChange={value => patch({ tTt: value })} />
            </div>
          </section>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Dòng phân bổ</h2>
            {!locked ? (
              <div className={df.headerActions}>
                <button type="button" className={df.btnAddLine} data-testid="ct-pb6-line-add-btn" onClick={addLine}>Thêm dòng</button>
                <button type="button" className={df.btnDeleteLine} data-testid="ct-pb6-line-remove-btn" disabled={selectedLineIndex == null} onClick={removeLine}>Xóa dòng</button>
              </div>
            ) : null}
            <div className={df.tableWrapper}>
              <table className={df.linesTable} data-testid="ct-pb6-line-grid">
                <thead>
                  <tr>
                    <th>Tk nợ</th>
                    <th>Tk có</th>
                    <th>Ngày phân bổ</th>
                    <th>Giá trị phân bổ kỳ</th>
                    <th>Diễn giải</th>
                    <th>Phát sinh VNĐ</th>
                    <th>V.Việc</th>
                    <th>Hợp đồng</th>
                    <th>khoản mục</th>
                    <th>Trung tâm lợi nhuận</th>
                    <th>Trung tâm chi phí</th>
                    <th>Phòng ban</th>
                    <th>Đ.Tượng nợ</th>
                    <th>Đ.Tượng có</th>
                  </tr>
                </thead>
                <tbody>
                  {form.lines.map((line, index) => (
                    <tr
                      key={index}
                      aria-selected={selectedLineIndex === index}
                      style={selectedLineIndex === index ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                      onClick={() => setSelectedLineIndex(index)}
                    >
                      <LineCell index={index} field="tkNo" value={line.tkNo} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="tkCo" value={line.tkCo} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="ngayCt00" value={line.ngayCt00} type="date" disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="tienNt" value={line.tienNt} inputMode="decimal" disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="dienGiaii" value={line.dienGiaii} maxLength={200} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="tien" value={line.tien} inputMode="decimal" disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="maVvI" value={line.maVvI} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="maHdI" value={line.maHdI} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="maPhiI" value={line.maPhiI} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="maTtlnI" value={line.maTtlnI} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="maTtcpI" value={line.maTtcpI} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="maBpI" value={line.maBpI} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="maKhN" value={line.maKhN} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="maKhC" value={line.maKhC} maxLength={30} disabled={locked} onChange={patchLine} />
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        </>
      ) : null}
      <UnsavedChangesModal
        isOpen={showUnsavedModal}
        onStay={cancelLeave}
        onLeave={confirmLeave}
        data-testid="ct-pb6-unsaved-modal"
      />
    </div>
  );
};

const TextField: React.FC<{
  label: string;
  testId: string;
  value: string;
  disabled: boolean;
  maxLength?: number;
  inputMode?: 'decimal' | 'numeric';
  onChange: (value: string) => void;
}> = ({ label, testId, value, disabled, maxLength, inputMode, onChange }) => (
  <div>
    <label className={df.label}>{label}</label>
    <Input
      data-testid={testId}
      value={value}
      maxLength={maxLength}
      inputMode={inputMode}
      disabled={disabled}
      onChange={event => onChange(event.target.value)}
    />
  </div>
);

const DateField: React.FC<{
  label: string;
  testId: string;
  value: string;
  disabled: boolean;
  onChange: (value: string) => void;
}> = ({ label, testId, value, disabled, onChange }) => (
  <div>
    <label className={df.label}>{label}</label>
    <Input type="date" data-testid={testId} value={value} disabled={disabled} onChange={event => onChange(event.target.value)} />
  </div>
);

const LineCell: React.FC<{
  index: number;
  field: keyof LineState;
  value: string;
  disabled: boolean;
  maxLength?: number;
  type?: string;
  inputMode?: 'decimal';
  onChange: (index: number, field: keyof LineState, value: string) => void;
}> = ({ index, field, value, disabled, maxLength, type, inputMode, onChange }) => (
  <td>
    <Input
      data-testid={`ct-pb6-line-${index}-${field}`}
      value={value}
      disabled={disabled}
      maxLength={maxLength}
      type={type}
      inputMode={inputMode}
      onChange={event => onChange(index, field, event.target.value)}
      onClick={event => event.stopPropagation()}
    />
  </td>
);

export default Pb6FormPage;
